class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def modify(root):
    def reverse_inorder_traversal(node, acc):
        if not node:
            return acc
        acc = reverse_inorder_traversal(node.right, acc)
        node.val += acc
        acc = node.val
        acc = reverse_inorder_traversal(node.left, acc)
        return acc

    reverse_inorder_traversal(root, 0)
    return root
